LEAN='/- Height semantics of closed GL fixed points on the chain 0<1<2<...:\n   a world of height h sees exactly heights g<h, so box phi holds at h iff phi holds at all g<h.\n   Gate agent W_n(X) = box( box^n False  or  (p and (q or not box q)) ),\n   p = "X cooperates with W_n", q = "X cooperates with DefectBot". W_2 is K6\'s W (size 12).\n   gate n p q is the formula under the outer box; W_n\'s action is bx (gate n p q). -/\n\ndef bx (φ : Nat → Prop) : Nat → Prop := fun h => ∀ g, g < h → φ g\ndef bxn : Nat → (Nat → Prop) → (Nat → Prop)\n  | 0, φ => φ\n  | n+1, φ => bx (bxn n φ)\n\ntheorem bxn_succ_iff (n : Nat) (φ : Nat → Prop) (h : Nat) :\n    bxn (n+1) φ h ↔ ∀ g, g + (n+1) ≤ h → φ g := by\n  induction n generalizing h with\n  | zero =>\n    simp only [bxn, bx]\n    exact ⟨fun H g hg => H g (by omega), fun H g hg => H g (by omega)⟩\n  | succ n ih =>\n    show bx (bxn (n+1) φ) h ↔ _\n    simp only [bx]\n    constructor\n    · intro H g hg\n      exact (ih (h-1)).1 (H (h-1) (by omega)) g (by omega)\n    · intro H g\' hg\'\n      exact (ih g\').2 (fun g hg => H g (by omega))\n\ntheorem bxn_iff (n : Nat) (hn : 1 ≤ n) (φ : Nat → Prop) (h : Nat) :\n    bxn n φ h ↔ ∀ g, g + n ≤ h → φ g := by\n  obtain ⟨m, rfl⟩ : ∃ m, n = m + 1 := ⟨n - 1, by omega⟩\n  exact bxn_succ_iff m φ h\n\ndef botn (n : Nat) : Nat → Prop := bxn n (fun _ => False)\n\ntheorem botn_iff (n h : Nat) : botn n h ↔ h < n := by\n  cases n with\n  | zero => simp [botn, bxn]\n  | succ m =>\n    unfold botn; rw [bxn_succ_iff]\n    constructor\n    · intro H; apply Classical.byContradiction; intro hn\n      exact H 0 (by omega)\n    · intro hlt g hg; omega\n\n\ndef ak (k : Nat) (p q : Nat → Prop) := bx (fun h => p h ∨ bxn k (fun g => ¬ (p g ∨ q g)) h)\ndef fair (j : Nat) (p : Nat → Prop) := bx (fun h => botn j h ∨ p h)\ndef prudent (j : Nat) (p q : Nat → Prop) := fun h => bx p h ∧ bxn (j+1) (fun g => ¬ q g) h\n\ntheorem bxn_true (k h : Nat) : bxn k (fun _ => True) h := by\n  induction k generalizing h with\n  | zero => trivial\n  | succ k ih => exact fun g _ => ih g\n\ntheorem ak_db (k h : Nat) : ak k (fun _ => False) (fun _ => False) h := by\n  intro g _\n  right\n  simpa using bxn_true k g\n\ntheorem prudent_db (j h : Nat) : prudent j (fun _ => False) (fun _ => False) h ↔ h = 0 := by\n  constructor\n  · intro H\n    apply Classical.byContradiction\n    intro hh\n    exact H.1 0 (by omega)\n  · intro hh\n    subst h\n    constructor\n    · intro g hg; omega\n    · apply (bxn_succ_iff j _ 0).2\n      intro g hg; omega\n\ntheorem ak_stag (k : Nat) (q : Nat → Prop) (h : Nat) : ak k (fun _ => True) q h := by\n  intro g _; exact Or.inl trivial\n\ntheorem pair_dominates_box (x y : Nat → Prop)\n    (hx : ∀ h, bx y h → x h) (hy : ∀ h, bx x h → y h) : ∀ h, x h ∧ y h := by\n  intro h\n  induction h using Nat.strongRecOn with\n  | ind h ih =>\n    exact ⟨hx h (fun g gh => (ih g gh).2), hy h (fun g gh => (ih g gh).1)⟩\n\ntheorem ak_pair (k m : Nat) (x y q r : Nat → Prop)\n    (hx : ∀ h, x h ↔ ak k y q h) (hy : ∀ h, y h ↔ ak m x r h) : ∀ h, x h ∧ y h := by\n  apply pair_dominates_box x y\n  · intro h H; apply (hx h).2; intro g gh; exact Or.inl (H g gh)\n  · intro h H; apply (hy h).2; intro g gh; exact Or.inl (H g gh)\n\ntheorem ak_fair (k j : Nat) (x y q : Nat → Prop)\n    (hx : ∀ h, x h ↔ ak k y q h) (hy : ∀ h, y h ↔ fair j x h) : ∀ h, x h ∧ y h := by\n  apply pair_dominates_box x y\n  · intro h H; apply (hx h).2; intro g gh; exact Or.inl (H g gh)\n  · intro h H; apply (hy h).2; intro g gh; exact Or.inr (H g gh)\n\n-- A\'s DB trace is True; prudent\'s DB trace holds only at zero.\ntheorem prudent_bound (j : Nat) (x y : Nat → Prop)\n    (hy : ∀ h, y h ↔ prudent j x (fun _ => True) h) :\n    y 0 ∧ ∀ h, j < h → ¬ y h := by\n  constructor\n  · apply (hy 0).2\n    constructor\n    · intro g hg; omega\n    · apply (bxn_succ_iff j _ 0).2; intro g hg; omega\n  · intro h hh yh\n    exact (bxn_succ_iff j _ h).1 ((hy h).1 yh).2 0 (by omega) trivial\n\ntheorem ak_prudent_zero (j : Nat) (x y : Nat → Prop)\n    (hx : ∀ h, x h ↔ ak 0 y (fun g => g = 0) h)\n    (hy : ∀ h, y h ↔ prudent j x (fun _ => True) h) :\n    (∀ h, x h) ∧ (∀ h, y h ↔ h ≤ j) := by\n  classical\n  have yy := (prudent_bound j x y hy).1\n  have xx : ∀ h, x h := by\n    intro h\n    apply (hx h).2\n    intro g gh\n    by_cases yg : y g\n    · exact Or.inl yg\n    · right\n      change ¬ (y g ∨ g = 0)\n      intro bad\n      rcases bad with bad | bad\n      · exact yg bad\n      · subst g; exact yg yy\n  refine ⟨xx, ?_⟩\n  intro h\n  constructor\n  · intro yh\n    apply Classical.byContradiction\n    intro hh\n    exact (prudent_bound j x y hy).2 h (by omega) yh\n  · intro hh\n    apply (hy h).2\n    constructor\n    · intro g _; exact xx g\n    · apply (bxn_succ_iff j _ h).2; intro g hg; omega\n\ntheorem ak_prudent_positive (k j : Nat) (hk : 1 ≤ k) (x y : Nat → Prop)\n    (hx : ∀ h, x h ↔ ak k y (fun g => g = 0) h)\n    (hy : ∀ h, y h ↔ prudent j x (fun _ => True) h) :\n    ∀ h, max k (j+1) < h → ¬ x h ∧ ¬ y h := by\n  intro h hh\n  have jj : j < h := by omega\n  refine ⟨?_, (prudent_bound j x y hy).2 h jj⟩\n  intro xh\n  have H := (hx h).1 xh (max k (j+1)) hh\n  rcases H with yg | bg\n  · exact (prudent_bound j x y hy).2 _ (by omega) yg\n  · have bad := (bxn_iff k hk _ _).1 bg 0 (by omega)\n    exact bad (Or.inr rfl)\n\n#print axioms ak_db\n#print axioms prudent_db\n#print axioms ak_stag\n#print axioms ak_pair\n#print axioms ak_fair\n#print axioms ak_prudent_zero\n#print axioms ak_prudent_positive\n\n-- Faithful graded PrudentBot: its guard exempts initial heights.\ndef pb (j : Nat) (p q : Nat → Prop) := fun h =>\n  bx p h ∧ bx (fun g => botn (j+1) g ∨ ¬ q g) h\n\ntheorem pb_db (j h : Nat) : pb j (fun _ => False) (fun _ => False) h ↔ h = 0 := by\n  constructor\n  · intro H\n    apply Classical.byContradiction\n    intro hh\n    exact H.1 0 (by omega)\n  · intro hh\n    subst h\n    constructor <;> intro g hg <;> omega\n\ntheorem pb_true (j : Nat) (x : Nat → Prop) (h : Nat) :\n    pb j x (fun _ => True) h ↔ prudent (j+1) x (fun _ => True) h := by\n  constructor\n  · intro H\n    refine ⟨H.1, ?_⟩\n    apply (bxn_succ_iff (j+1) _ h).2\n    intro g hg\n    have bad := H.2 (j+1) (by omega)\n    rcases bad with bad | bad\n    · have := (botn_iff (j+1) (j+1)).1 bad; omega\n    · exact bad\n  · intro H\n    refine ⟨H.1, ?_⟩\n    intro g gh\n    left\n    apply (botn_iff (j+1) g).2\n    apply Classical.byContradiction\n    intro bad\n    have hh : 0 + (j+1+1) ≤ h := by omega\n    exact (bxn_succ_iff (j+1) _ h).1 H.2 0 hh trivial\n\ntheorem ak_pb_zero (j : Nat) (x y : Nat → Prop)\n    (hx : ∀ h, x h ↔ ak 0 y (fun g => g = 0) h)\n    (hy : ∀ h, y h ↔ pb j x (fun _ => True) h) :\n    (∀ h, x h) ∧ (∀ h, y h ↔ h ≤ j+1) := by\n  exact ak_prudent_zero (j+1) x y hx (fun h => (hy h).trans (pb_true j x h))\n\ntheorem ak_pb_positive (k j : Nat) (hk : 1 ≤ k) (x y : Nat → Prop)\n    (hx : ∀ h, x h ↔ ak k y (fun g => g = 0) h)\n    (hy : ∀ h, y h ↔ pb j x (fun _ => True) h) :\n    ∀ h, max k (j+2) < h → ¬ x h ∧ ¬ y h := by\n  exact ak_prudent_positive k (j+1) hk x y hx (fun h => (hy h).trans (pb_true j x h))\n\n#print axioms pb_db\n#print axioms pb_true\n#print axioms ak_pb_zero\n#print axioms ak_pb_positive\n'
lean = shutil.which('lean') or '/opt/elan/bin/lean'
with tempfile.TemporaryDirectory() as d:
    p=pathlib.Path(d)/'proof.lean'
    p.write_text(LEAN)
    r=subprocess.run([lean,str(p)],capture_output=True,text=True,timeout=60)
    assert r.returncode==0,(r.stdout,r.stderr)
    assert 'sorryAx' not in r.stdout
    assert r.stdout.count("axioms")==11
    print(r.stdout)
    # Strict instead of weak bound would falsely force prudent to hare at height j.
    bad=LEAN.replace('(∀ h, y h ↔ h ≤ j)', '(∀ h, y h ↔ h < j)')
    assert bad!=LEAN
    p.write_text(bad)
    r=subprocess.run([lean,str(p)],capture_output=True,text=True,timeout=60)
    assert r.returncode!=0, 'false boundary mutation accepted'
A=lambda k:'[](p|'+'[]'*k+'~(p|q))'
F=lambda j:'[]('+'[]'*j+'F|p)'
PB=lambda j:'([]p&[]('+'[]'*(j+1)+'F|~q))'
P=lambda j:'([]p&'+'[]'*(j+1)+'~q)'
count=0
for k in range(9):
    for b,expected in [('F',(True,False)),('~F',(True,True))]:
        assert ns['game'](A(k),b)==expected
        count+=1
    for j in range(9):
        for b,expected in [(A(j),(True,True)),(F(j),(True,True)),(P(j),(k==0,False)),(PB(j),(k==0,False))]:
            assert ns['game'](A(k),b)==expected,(k,j,b)
            count+=1
heads=[(A(0),P(0),(True,False)),(A(1),P(0),(False,False)),
       (A(3),P(4),(False,False)),(A(3),A(1),(True,True)),
       (A(3),F(4),(True,True)),(A(3),'F',(True,False)),
       (A(3),'~F',(True,True)),(A(3),A(3),(True,True))]
heads += [(A(0),PB(0),(True,False)),(A(3),PB(2),(False,False)),(PB(0),PB(0),(True,True)),(PB(0),'[]p',(True,True))]
for a,b,expected in heads:
    assert ns['solve'](a,b)==expected,(a,b)
print('PASS: eleven Lean theorems; false mutation rejected;',count,'height cells;',len(heads),'GLS fixed-point certificates')
